// Get all scheduled alarms
export async function getAllAlarms() {
  try {
    const alarms = await chrome.alarms.getAll();
    return alarms;
  } catch (error) {
    console.error('[Reminders] Error getting all alarms:', error);
    return [];
  }
}

// Sync alarms with storage (on startup or reload)
export async function syncAlarmsWithStorage() {
  try {
    console.log('[Reminders] Syncing alarms with storage');

    // Get all reminders from storage
    const reminders = await getAllReminders();
    console.log('[Reminders] Found reminders:', reminders.length);

    // If no reminders, nothing to sync
    if (reminders.length === 0) {
      console.log('[Reminders] No reminders to sync');
      return;
    }

    // Get all current alarms
    const alarms = await getAllAlarms();
    console.log('[Reminders] Found alarms:', alarms.length);

    // Clear orphaned alarms (alarms without corresponding reminders)
    for (const alarm of alarms) {
      if (alarm.name.startsWith('snooze_')) continue;

      const reminder = reminders.find(r => r.id === alarm.name);
      if (!reminder) {
        console.log('[Reminders] Clearing orphaned alarm:', alarm.name);
        await chrome.alarms.clear(alarm.name);
      }
    }

    // Process each reminder
    const now = Date.now();
    for (const reminder of reminders) {
      try {
        console.log('[Reminders] Processing reminder:', reminder.id);

        // Validate reminder has required fields
        if (!reminder.id || !reminder.repeatType || !reminder.nextTrigger) {
          console.error('[Reminders] Skipping invalid reminder (missing required fields):', reminder);
          continue;
        }

        if (reminder.paused) {
          // Clear alarm for paused reminders
          console.log('[Reminders] Reminder is paused, clearing alarm');
          await chrome.alarms.clear(reminder.id);
          continue;
        }

        // Check if reminder was missed
        if (reminder.nextTrigger <= now) {
          console.log('[Reminders] Missed reminder detected:', reminder.id);

          // Show missed notification immediately
          try {
            await showReminderNotification(reminder);
          } catch (err) {
            console.error('[Reminders] Error showing notification:', err);
            console.error('[Reminders] Stack:', err.stack);
          }

          // Recalculate next trigger
          if (reminder.repeatType !== 'once') {
            const nextTrigger = calculateNextTriggerTime(reminder);
            await updateReminder(reminder.id, { nextTrigger });
            await scheduleReminder({ ...reminder, nextTrigger });
          }
        } else {
          // Schedule or reschedule the alarm
          console.log('[Reminders] Scheduling reminder for future trigger');
          await scheduleReminder(reminder);
        }
      } catch (err) {
        console.error('[Reminders] Error processing reminder:', reminder?.id || 'unknown', err);
        console.error('[Reminders] Error stack:', err.stack);
      }
    }

    console.log('[Reminders] Alarm sync complete');
  } catch (error) {
    console.error('[Reminders] Error syncing alarms:', error);
    console.error('[Reminders] Stack:', error.stack);
    // Don't throw - allow service worker to continue
  }
}

// Toggle reminder paused state
export async function toggleReminderPaused(id) {
  try {
    const reminder = await getReminder(id);
    if (!reminder) {
      throw new Error(`Reminder ${id} not found`);
    }

    const newPausedState = !reminder.paused;
    await updateReminder(id, { paused: newPausedState });

    if (newPausedState) {
      // Clear alarm when pausing
      await clearReminder(id);
    } else {
      // Schedule alarm when resuming
      await scheduleReminder({ ...reminder, paused: false });
    }

    console.log('[Reminders] Toggled pause state:', id, newPausedState);
    return newPausedState;
  } catch (error) {
    console.error('[Reminders] Error toggling pause:', error);
    throw error;
  }
}

// Generate human-readable summary of reminder repeat pattern
export function generateReminderSummary(reminder) {
  const config = reminder.repeatConfig || reminder;

  switch (reminder.repeatType) {
    case 'once':
      return 'Once';

    case 'hourly':
      return config.interval === 1 
        ? 'Every hour' 
        : `Every ${config.interval} hours`;

    case 'daily':
      return 'Every day';

    case 'weekly': {
      if (!config.weekdays || config.weekdays.length === 0) {
        return 'Weekly';
      }
      const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
      const days = config.weekdays
        .sort((a, b) => a - b)
        .map(d => dayNames[d])
        .join(', ');
      return `Every ${days}`;
    }

    case 'monthly':
      return `Monthly on day ${config.dayOfMonth || 1}`;

    case 'custom': {
      const { interval, unit } = config;
      const unitLabel = interval === 1 
        ? unit.slice(0, -1) 
        : unit;
      return `Every ${interval} ${unitLabel}`;
    }

    default:
      return 'Unknown';
  }
}

// Date Utilities
// Helper functions for date/time handling and formatting

// Format a timestamp to readable date/time string
export function formatDateTime(timestamp) {
  const date = new Date(timestamp);
  return date.toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  });
}

// Format a timestamp to time only
export function formatTime(timestamp) {
  const date = new Date(timestamp);
  return date.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  });
}

// Format a timestamp to date only
export function formatDate(timestamp) {
  const date = new Date(timestamp);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  });
}

// Get relative time description (e.g., "in 5 minutes", "2 hours ago")
export function getRelativeTime(timestamp) {
  const now = Date.now();
  const diff = timestamp - now;
  const absDiff = Math.abs(diff);

  const minute = 60 * 1000;
  const hour = 60 * minute;
  const day = 24 * hour;

  if (absDiff < minute) {
    return diff > 0 ? 'in less than a minute' : 'just now';
  } else if (absDiff < hour) {
    const minutes = Math.floor(absDiff / minute);
    return diff > 0 
      ? `in ${minutes} minute${minutes > 1 ? 's' : ''}`
      : `${minutes} minute${minutes > 1 ? 's' : ''} ago`;
  } else if (absDiff < day) {
    const hours = Math.floor(absDiff / hour);
    return diff > 0
      ? `in ${hours} hour${hours > 1 ? 's' : ''}`
      : `${hours} hour${hours > 1 ? 's' : ''} ago`;
  } else {
    const days = Math.floor(absDiff / day);
    return diff > 0
      ? `in ${days} day${days > 1 ? 's' : ''}`
      : `${days} day${days > 1 ? 's' : ''} ago`;
  }
}

// Check if a timestamp is in the past
export function isPast(timestamp) {
  return timestamp < Date.now();
}

// Check if a timestamp is today
export function isToday(timestamp) {
  const date = new Date(timestamp);
  const today = new Date();
  return date.toDateString() === today.toDateString();
}

// Add minutes to a timestamp
export function addMinutes(timestamp, minutes) {
  return timestamp + (minutes * 60 * 1000);
}

// Add hours to a timestamp
export function addHours(timestamp, hours) {
  return timestamp + (hours * 60 * 60 * 1000);
}

// Add days to a timestamp
export function addDays(timestamp, days) {
  return timestamp + (days * 24 * 60 * 60 * 1000);
}

// Round timestamp to nearest minute
export function roundToMinute(timestamp) {
  return Math.round(timestamp / (60 * 1000)) * (60 * 1000);
}

// Calculate next trigger time for a reminder
export function calculateNextTriggerTime(reminder) {
  const now = Date.now();

  // Support both old structure (direct properties) and new structure (repeatConfig)
  const config = reminder.repeatConfig || reminder;

  switch (reminder.repeatType) {
    case 'once': {
      // For once reminders, use the original datetime
      if (reminder.datetime) {
        return new Date(reminder.datetime).getTime();
      }
      return reminder.nextTrigger || now + (5 * 60 * 1000);
    }

    case 'hourly': {
      const interval = config.interval || 1;
      const intervalMs = interval * 60 * 60 * 1000;

      // If we have a previous trigger, use that as base
      if (reminder.nextTrigger && reminder.nextTrigger > 0) {
        let next = reminder.nextTrigger;
        // Keep adding interval until we're in the future
        while (next <= now) {
          next += intervalMs;
        }
        return next;
      }

      // First time, start from now
      return now + intervalMs;
    }

    case 'daily': {
      const [hours, minutes] = (config.time || '09:00').split(':').map(Number);
      const next = new Date();
      next.setHours(hours, minutes, 0, 0);

      // If time has passed today, move to tomorrow
      if (next.getTime() <= now) {
        next.setDate(next.getDate() + 1);
      }

      return next.getTime();
    }

    case 'weekly': {
      const weekdays = config.weekdays || [1];
      const [hours, minutes] = (config.time || '09:00').split(':').map(Number);

      const next = new Date();
      next.setHours(hours, minutes, 0, 0);

      let daysToAdd = 0;
      let currentDay = next.getDay();

      // If today's time has passed, start from tomorrow
      if (next.getTime() <= now) {
        daysToAdd = 1;
        currentDay = (currentDay + 1) % 7;
      }

      // Find the next day in weekdays array
      let attempts = 0;
      while (!weekdays.includes(currentDay) && attempts < 7) {
        daysToAdd++;
        currentDay = (currentDay + 1) % 7;
        attempts++;
      }

      // If no valid day found, default to tomorrow
      if (attempts >= 7) {
        daysToAdd = 1;
      }

      next.setDate(next.getDate() + daysToAdd);
      return next.getTime();
    }

    case 'monthly': {
      const day = config.dayOfMonth || 1;
      const [hours, minutes] = (config.time || '09:00').split(':').map(Number);

      const next = new Date();
      next.setHours(hours, minutes, 0, 0);

      // Try to set to the target day of this month
      const currentMonth = next.getMonth();
      next.setDate(day);

      // If the date overflowed to next month (e.g., Feb 31 -> Mar 3)
      // or if the time has passed this month, move to next month
      if (next.getMonth() !== currentMonth || next.getTime() <= now) {
        next.setMonth(currentMonth + 1);
        next.setDate(1); // Start from first of next month
        next.setDate(day);

        // Handle overflow again (e.g., setting day 31 in a 30-day month)
        const targetMonth = (currentMonth + 1) % 12;
        if (next.getMonth() !== targetMonth) {
          // Use last day of target month
          next.setDate(0); // Go back to last day of previous month
        }
      }

      return next.getTime();
    }

    case 'custom': {
      const interval = config.interval || 1;
      const unit = config.unit || 'hours';

      let intervalMs = 0;
      switch (unit) {
        case 'minutes':
          intervalMs = interval * 60 * 1000;
          break;
        case 'hours':
          intervalMs = interval * 60 * 60 * 1000;
          break;
        case 'days':
          intervalMs = interval * 24 * 60 * 60 * 1000;
          break;
      }

      // If we have a previous trigger, use that as base
      if (reminder.nextTrigger && reminder.nextTrigger > 0) {
        let next = reminder.nextTrigger;
        // Keep adding interval until we're in the future
        while (next <= now) {
          next += intervalMs;
        }
        return next;
      }

      // First time, start from now
      return now + intervalMs;
    }

    default:
      return now + (5 * 60 * 1000);
  }
}

